//! Regenerate: rustc --edition 2024 scripts/generate_music_note_colors.rs -O -o target/pitch-stage4-validation/generate_music_note_colors.exe
//! Run from the repository root, then rustfmt src/music_note_color/table.rs.
//! Does not launch the product.
#[path = "../src/music_note_color/compute.rs"]
mod compute;

fn main() {
    let started = std::time::Instant::now();
    let table = compute::generate_table();
    println!(
        "music_note_color_table_generation_ms={:.3}",
        started.elapsed().as_secs_f64() * 1000.0
    );
    let mut output = String::from(
        "// Generated by scripts/generate_music_note_colors.rs. Do not edit by hand.\n\npub(super) static NOTE_COLORS: [[[[u8; 3]; 256]; 12]; 2] = [\n",
    );
    for scheme in table {
        output.push_str("    [\n");
        for pc in scheme {
            output.push_str("        [\n");
            for group in pc.chunks(8) {
                output.push_str("            ");
                for [r, g, b] in group {
                    output.push_str(&format!("[{r}, {g}, {b}], "));
                }
                output.push('\n');
            }
            output.push_str("        ],\n");
        }
        output.push_str("    ],\n");
    }
    output.push_str("];\n");
    std::fs::write("src/music_note_color/table.rs", output).unwrap();
}
